 "content": "def transform(grid):
    """Connect consecutive same-row/column marked cells with color 3."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (1, 9)]
    # Input background is 1 or 9; every other color is a point marker.
    for r in range(h):
        cols = [c for rr, c in points if rr == r]
        cols.sort()
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 1, b):
                out[r][c] = 3
    for c in range(w):
        rows = [r for r, cc in points if cc == c]
        rows.sort()
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                out[r][c] = 3
    return out
